/// Names for a variable id under `revision` (`None` when out of range).
pub fn variable_name(revision: V4Revision, id: i32) -> Option<&'static str> {
    if id < 0 {
        return None;
    }
    table(revision).get(id as usize).copied()
}

/// Reverse lookup of [`variable_name`]; exact, case-sensitive match.
pub fn variable_id(revision: V4Revision, name: &str) -> Option<i32> {
    table(revision)
        .iter()
        .position(|candidate| *candidate == name)
        .map(|index| index as i32)
}

fn table(revision: V4Revision) -> &'static [&'static str] {
    match revision {
        V4Revision::Rev00 => VAR_NAMES_REV00,
        V4Revision::Rev01 => VAR_NAMES_REV01,
        V4Revision::Rev02 => VAR_NAMES_REV02,
        V4Revision::Rev03 => VAR_NAMES_REV03,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::version::V4Revision;

    #[test]
    fn counts_match_upstream_gating() {
        assert_eq!(table(V4Revision::Rev00).len(), 241);
        assert_eq!(table(V4Revision::Rev01).len(), 244);
        assert_eq!(table(V4Revision::Rev02).len(), 244);
        assert_eq!(table(V4Revision::Rev03).len(), 251);
    }

    #[test]
    fn core_variable_ids_are_stable_across_revisions() {
        for revision in V4Revision::ALL {
            assert_eq!(variable_name(revision, VAR_TEMP0), Some("temp0"));
            assert_eq!(variable_name(revision, VAR_TEMP7), Some("temp7"));
            assert_eq!(
                variable_name(revision, VAR_CHECK_RESULT),
                Some("checkResult")
            );
            assert_eq!(variable_name(revision, VAR_ARRAY_POS0), Some("arrayPos0"));
            assert_eq!(variable_name(revision, VAR_ARRAY_POS7), Some("arrayPos7"));
            assert_eq!(variable_name(revision, VAR_GLOBAL), Some("global"));
            assert_eq!(variable_name(revision, VAR_LOCAL), Some("local"));
            assert!(variable_id(revision, "object.xpos").is_some());
        }
    }

    #[test]
    fn revision_gated_variables_appear_only_where_upstream_defines_them() {
        assert_eq!(
            variable_id(V4Revision::Rev03, "screen.currentID"),
            Some(243)
        );
        assert_eq!(variable_id(V4Revision::Rev02, "screen.currentID"), None);
        assert_eq!(variable_id(V4Revision::Rev00, "engine.message"), Some(233));
        assert_eq!(variable_id(V4Revision::Rev03, "engine.message"), None);
        assert_eq!(variable_id(V4Revision::Rev00, "engine.deviceType"), None);
        assert!(variable_id(V4Revision::Rev01, "engine.deviceType").is_some());
    }

    #[test]
    fn every_entry_round_trips() {
        for revision in V4Revision::ALL {
            for (index, name) in table(revision).iter().enumerate() {
                assert_eq!(variable_name(revision, index as i32), Some(*name));
                assert_eq!(variable_id(revision, name), Some(index as i32));
            }
            assert_eq!(variable_name(revision, -1), None);
            assert_eq!(variable_name(revision, 10_000), None);
        }
    }
}
